function renderCurrent(){const year=ui.selected,r=displayRecord(year),isFuture=year>ui.run.year;$('#now-section').hidden=false;$('#view-kind').className='kind-tag '+(r?.kind||'simulation');$('#view-kind').textContent=r?KIND[r.kind]||'人生片段':'尚未展开';$('#view-year').textContent=`${year} · ${year-min}岁`;$('#return-live').hidden=year===ui.run.year;$('#return-live').textContent=`回到 ${ui.run.year} 年 →`;const img=$('#year-scene');if(img.getAttribute('src')!==yearImage(year))img.src=yearImage(year);img.alt=imageNote(year);$('#image-note').textContent=imageNote(year);$('#scene-location').textContent=r?.location|| (year===ui.run.year?ui.run.location:'地点未在此记录');$('#scene-vocation').textContent=r?.vocation||'';$('#current-title').textContent=r?.title||(isFuture?'这一年，还没有写下。':'这一页，暂时没有记录。');$('#current-summary').textContent=r?.summary||(isFuture?'继续让时间流动，重心、状态与选择会让这一年长出新的故事。':'年格可以回看，资料缺口仍然保留。');const paragraphs=A(r?.paragraphs).filter(p=>typeof p==='string'&&p.trim()&&p.trim()!==r.summary?.trim());$('#current-paragraphs').innerHTML=paragraphs.slice(0,3).map(p=>`<p>${E(p)}</p>`).join('')+(paragraphs.length>3?`<details class="remaining-story"><summary>继续读完这一年 <span>还有 ${paragraphs.length-3} 段</span></summary>${paragraphs.slice(3).map(p=>`<p>${E(p)}</p>`).join('')}</details>`:'');$('#current-events').innerHTML=A(r?.events).map((event,i)=>`<details class="event-detail-collapse"><summary><span>${E(event.title||'一个片段')}</span><small>${E(statLabel(event.dimension||''))}</small></summary><p>${E(event.text||'')}</p>${effectMarkup(event.effectsApplied||event.effects)?`<span class="event-effect">模拟变化 / ${E(effectMarkup(event.effectsApplied||event.effects))}</span>`:''}<button data-event-audit="${i}">${number(event.probability)===null?'查看记录来处':'查看这次抽选依据'} ↗</button></details>`).join('');const decision=r?.decision,chosen=decision&&typeof decision==='object'?(decision.outcome||decision.selectedOutcome||decision.result?.outcome):null;const chosenOption=A(decision?.options).find(o=>o.id===decision?.selectedOptionId);$('#current-outcome').innerHTML=chosen?`<span>这一年，你这样做了</span>${chosenOption?`<strong>${E(chosenOption.label||textField(chosenOption.action||chosenOption.human?.action))}</strong>`:''}<p>${E(chosen)}</p>${effectMarkup(decision?.effectsApplied)?`<details class="outcome-numbers"><summary>看实际数值变化</summary><p>${E(effectMarkup(decision.effectsApplied))}</p></details>`:''}`:'';$('#favorite-current').disabled=!r;$('#favorite-current').setAttribute('aria-pressed',String(ui.favorites.has(year)));$('#favorite-current').textContent=ui.favorites.has(year)?'★':'☆';const historyLink=$('#read-year-link');historyLink.textContent=year<=cutoff?'核对这一年的来处 ↗':'看命盘依据 ↗';historyLink.href=year<=cutoff?`storybook.html#biography-${year}`:'#year-astrology';historyLink.onclick=year>cutoff?(event)=>{event.preventDefault();openYearAudit();}:null;$('#fork-selected').disabled=year>ui.run.year||Boolean(ui.run.pending);$('#boundary-note').hidden=!(ui.run.ended&&year===max);$$('[data-event-audit]').forEach(button=>button.addEventListener('click',()=>openYearAudit(Number(button.dataset.eventAudit))));$$('#current-paragraphs details, #current-events details').forEach(detail=>detail.addEventListener('toggle',()=>{if(detail.open)pause();}));}
