function renderLifeContext(){const r=displayRecord(ui.selected),live=ui.selected===ui.run.year,project=live?ui.run.project:null,people=live?A(ui.run.people):[],status={active:'正在进行',paused:'暂时放下',done:'已完成',completed:'已完成',testing:'正在试用',exploring:'探索之中',ended:'已经收束',prototype:'原型阶段'};$('#context-year').textContent=ui.selected;$('#life-context-content').innerHTML=`<div class="life-context-list"><div class="context-item"><span>身在何处</span><strong>${E(r?.location||(live?ui.run.location:'本页未具体记录'))}</strong></div><div class="context-item"><span>手里的事情</span><strong>${E(r?.vocation||(live?ui.run.vocation:'不由命盘替经历补写'))}</strong></div>${project?.name?`<div class="context-item"><span>正在靠近的作品</span><strong>${E(project.name)}</strong>${project.status?`<p>${E(status[project.status]||(/[\u3400-\u9fff]/.test(project.status)?project.status:''))}</p>`:''}</div>`:''}</div>${people.length?people.slice(-4).map(p=>`<div class="person-line"><strong>${E(typeof p==='string'?p:p.label||p.name||({collaborator:'一位合作者',friend:'一位朋友',partner:'亲密同行者',mentor:'一位前辈'})[p.role]||'一位同行者')}</strong><span>${E(typeof p==='object'?p.description||p.relation||p.summary||({collaborator:'在共同的事情里认识',friend:'留下过一起相处的时间',partner:'这条模拟支线里明确选择的关系',mentor:'在某段手艺上相互交流'})[p.role]||'':'')}</span></div>`).join(''):`<p class="context-note">${live?'关系只随故事写入，不预设家庭角色。':'这是对这一年的回看；当时未被记录的人不另行补造。'}</p>`}`;}
function curveSvg(series,{minYear,maxYear,height=145,labels=true}={}){const width=500,h=height,pad={l:25,r:13,t:12,b:25},all=series.flatMap(s=>s.points).filter(p=>number(p.value)!==null);const from=minYear??Math.min(...all.map(p=>p.year)),to=maxYear??Math.max(...all.map(p=>p.year)),span=Math.max(1,to-from),x=y=>pad.l+(y-from)/span*(width-pad.l-pad.r),y=v=>h-pad.b-Math.max(0,Math.min(100,v))/100*(h-pad.t-pad.b);if(!all.length)return'<p class="empty-line">时间再往前，曲线会留下更多痕迹。</p>';return`<svg viewBox="0 0 ${width} ${h}" role="img" aria-label="${E(series.map(s=>s.name).join('与'))}走势"><title>${E(series.map(s=>s.name).join('与'))}，0至100的游戏状态或编辑信号</title>${[0,50,100].map(v=>`<line class="chart-grid" x1="${pad.l}" x2="${width-pad.r}" y1="${y(v)}" y2="${y(v)}"/><text class="chart-axis" x="2" y="${y(v)+3}">${v}</text>`).join('')}${series.map(s=>{const points=s.points.filter(p=>number(p.value)!==null).sort((a,b)=>a.year-b.year);const path=points.map((p,i)=>`${i?'L':'M'}${x(p.year).toFixed(1)},${y(p.value).toFixed(1)}`).join(' ');return`<path class="chart-line" d="${path}" stroke="${E(s.color)}"/>${points.length===1?`<circle class="chart-point" cx="${x(points[0].year)}" cy="${y(points[0].value)}" r="4" fill="${E(s.color)}"/>`:''}`;}).join('')}${labels?`<text class="chart-axis" x="${pad.l}" y="${h-5}">${from}</text><text class="chart-axis" x="${width-pad.r}" y="${h-5}" text-anchor="end">${to===from?'':to}</text>`:''}</svg>`;}
function runPoints(run,metric){const points=A(run.timeline).filter(r=>number(r.stats?.[metric])!==null).map(r=>({year:r.year,value:r.stats[metric]}));if(!points.some(p=>p.year===run.year)&&number(run.stats?.[metric])!==null)points.push({year:run.year,value:run.stats[metric]});return points;}
function renderCurves(){$('#state-chart').innerHTML=curveSvg([{name:statLabel(ui.metric),color:statColor(ui.metric),points:runPoints(ui.run,ui.metric)}],{minYear:Math.min(ui.run.year,...A(ui.run.timeline).map(r=>r.year)),maxYear:ui.run.year});$('#natal-chart').innerHTML=curveSvg([{name:'命盘净势编辑信号',color:'#708b66',points:A(D.years).map(y=>({year:y.year,value:S.years?.[y.year]?.trend?.balance??y.scores?.overall}))}],{minYear:min,maxYear:max,height:150});}
function renderSharp(){const s=sharp(ui.selected);$('#sharp-year').textContent=ui.selected;$('#sharp-content').innerHTML=s.headline?`<h3>${E(s.headline)}</h3><div class="sharp-angles">${[['主攻',s.upside],['代价',s.price],['避坑',s.pitfall]].map(([label,text])=>text?`<div class="sharp-angle"><span>${label}</span><p>${E(text)}</p></div>`:'').join('')}</div><details class="sharp-details"><summary>原判断与主星依据 ↗</summary>${s.verdict?`<p>${E(s.verdict)}</p>`:''}<ul>${A(s.claimBasis).map(v=>`<li>${E(typeof v==='string'?v:v.text||v.title||'')}</li>`).join('')}</ul><p>命盘层是传统象义与编辑信号，不证明某一公历事件由它造成。</p></details>`:'<p class="empty-line">本年未加载单独判断；完整排盘仍可到资料馆查看。</p>';}
function renderAll(){if(!ui.run)return;$('#engine-status').hidden=true;renderControls();renderProfile();renderCurrent();renderYearDilemma();renderStream();renderLifeContext();renderStars();renderMap();renderCurves();renderSharp();}
function viewYear(year,scroll=false){if(!yearValid(year)||!ui.run)return;pause();ui.selected=Number(year);renderAll();if(scroll)$('#now-section').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}
function step(){if(!ui.run)return;clearTimeout(ui.timer);clearInterval(ui.progress);if(ui.run.pending&&!ui.autoChoose){pause();showDecision();return;}try{const next=api.advance(ui.run,{autoChoose:ui.autoChoose});ui.run=next;ui.selected=next.year;store();renderAll();if(next.pending&&!ui.autoChoose){pause();showDecision();}else if(next.ended){pause();toast('这条支线走到2100年的展示边界，故事仍可回看。');}else schedule();}catch(error){pause();toast(error.message||'这一年暂时未能展开，原进度仍在。');}}
function manualStep(){pause();if(ui.run?.pending&&!ui.autoChoose){showDecision();return;}step();}
function axisFor(year,record=displayRecord(year)){if(record?.yearContext)return record.yearContext;try{const value=api?.getYearContext(year)?.yearContext;if(value)return value;const fallback=window.TANG_ZIWEI?.getYearContext?.(year);return fallback?.yearContext||fallback||null;}catch(_){return null;}}
function axisProofMarkup(axis){if(!axis)return'';const basis=A(axis.starBasis),evidence=A(axis.evidence);return`${basis.length?`<ul class="axis-star-basis">${basis.map(text=>`<li>${E(text)}</li>`).join('')}</ul>`:''}${evidence.length?`<details class="axis-full-evidence"><summary>逐项落宫与主轴对照 · ${evidence.length} 条</summary><ul>${evidence.map(item=>`<li>${E(typeof item==='string'?item:item.text||'')}</li>`).join('')}</ul></details>`:''}`;}
function renderYearDilemma(){const target=$('#year-dilemma'),record=displayRecord(ui.selected),axis=axisFor(ui.selected,record);if(!axis||!(axis.question||axis.headline||axis.title)){target.hidden=true;target.innerHTML='';return;}const mainTheme=A(axis.themes).find(t=>t.id===axis.primaryThemeId)||A(axis.themes)[0],past=['recorded','gap'].includes(record?.kind);target.hidden=false;target.innerHTML=`<div class="year-axis-kicker"><span>${past?'这一年的命理提问':ui.selected===ui.run.year?'今年的难题':'那一年的难题'}</span>${mainTheme?.label?`<small>${E(mainTheme.label)}</small>`:''}</div><h3>${E(axis.question||axis.headline||axis.title)}</h3>${axis.conflict?`<p class="year-axis-conflict">${E(axis.conflict)}</p>`:''}${axis.stakes?`<p class="year-axis-stakes">${E(axis.stakes)}</p>`:''}<details class="year-axis-proof"><summary>为什么是这一题？看主星与限年叠化 ↗</summary>${axisProofMarkup(axis)}<button data-axis-chart>展开三层四化与完整宫位依据 ↗</button></details>`;target.querySelector('[data-axis-chart]')?.addEventListener('click',openChartDetail);}
function textField(value){if(typeof value==='string'||typeof value==='number')return String(value);if(Array.isArray(value))return value.filter(v=>typeof v==='string').join('；');return'';}
function optionFacts(option){const human=option.human&&typeof option.human==='object'?option.human:{};const fields=[['要花',option.time||option.timeCost||option.duration||human.time],['影响谁',option.people||option.socialImpact||option.socialEffect||human.people],['代价',option.cost||option.tradeoff||option.humanCost||human.cost]];return fields.map(([label,value])=>[label,textField(value)]).filter(([,value])=>value);}
function showDecision(){
 if(!ui.run?.pending)return;pause();const d=ui.run.pending,axis=axisFor(d.year||ui.run.year);
 $('#decision-year').textContent=`${d.year||ui.run.year} · ${(d.year||ui.run.year)-min}岁 / 这一次，怎么做`;
 $('#decision-title').textContent=d.title||'下一步，从这里分开。';$('#decision-prompt').textContent=d.prompt||'看看每种做法会花掉什么，再选一次。';
 const context=$('#decision-context');context.hidden=!axis;if(axis){
  const tags=new Set(A(d.astroThemes)),isMain=tags.has(axis.primaryThemeId),matched=A(axis.themes).filter(t=>tags.has(t.id));
  const evidence=A(axis.evidence).filter(item=>A(item.themeIds).some(id=>tags.has(id)));
  const priority=item=>item.kind==='same-star-overlap'?0:item.layer==='annual'?1:item.id==='frame-annual'?2:3;
  const basis=evidence.slice().sort((a,b)=>priority(a)-priority(b)).slice(0,4).map(item=>item.text);
  const proof={starBasis:basis,evidence},label=isMain?'这一年的核心难题':'这一年的生活支线';
  context.innerHTML=`<span>${label}</span>${isMain?`<strong>${E(axis.question||axis.title)}</strong>`:matched.length?`<p>${E(matched.map(t=>t.label).join(' · '))}</p>`:''}<details><summary>这项选择对应哪些盘据 ↗</summary>${axisProofMarkup(proof)}</details>`;
 }
 $('#decision-options').innerHTML=A(d.options).map((o,i)=>{const facts=optionFacts(o),action=textField(o.action||o.human?.action),title=o.label||action,narrative=action||(o.description||o.story||'');return`<article class="decision-option-card"><button class="decision-option decision-action" data-decide="${E(o.id)}"><small>0${i+1}</small><div><strong>${E(title)}</strong>${narrative&&narrative!==title?`<p>${E(narrative)}</p>`:''}${facts.length?`<dl class="decision-human-facts">${facts.map(([label,text])=>`<div><dt>${label}</dt><dd>${E(text)}</dd></div>`).join('')}</dl>`:''}<span class="decision-do">就这样做 →</span></div></button>${effectMarkup(o.effects)?`<details class="decision-numbers"><summary>看数值变化</summary><p>${E(effectMarkup(o.effects))}</p><small>游戏基础变化，实际写入还受当时状态影响。</small></details>`:''}</article>`;}).join('');
 $$('[data-decide]').forEach(button=>button.addEventListener('click',()=>{try{const option=A(d.options).find(o=>o.id===button.dataset.decide);ui.run=api.decide(ui.run,button.dataset.decide);ui.selected=ui.run.year;$('#decision-dialog').close();store();renderAll();if(option?.outcome)toast(option.outcome);else toast('这一年的决定已经写下。等你准备好，再往前走。');}catch(error){toast(error.message||'这个选择暂时无法写入。');}}));
 ui.lastDecisionId=d.id;if(!$('#decision-dialog').open)$('#decision-dialog').showModal();
}
function legacyImportNotice(){modal('这份存档来自上一版',`<p>上一版的支线、进度与选项完整保留。请到旧页导入和继续；新版会使用另一份独立存档。</p><div class="dialog-buttons"><a class="dialog-action primary" href="previous-edition.html">回看上一版支线 →</a></div>`,'PREVIOUS EDITION / 上一版');}
async function importFile(file){if(!file)return;pause();try{if(file.size>16000000)throw new Error('文件过大，请导入本模拟器导出的支线存档。');const raw=await file.text(),parsed=JSON.parse(raw),inside=typeof parsed?.current==='string'?JSON.parse(parsed.current):parsed;if(parsed?.version===1||inside?.version===1){legacyImportNotice();return;}if(ui.run&&!canAddBranch())return;const next=api.importRun(typeof parsed?.current==='string'?parsed.current:raw),previous=ui.run?snapshotCurrent():null;if(previous)ui.branches.push(previous);ui.run=next;ui.selected=next.year;ui.branchId='import-'+Date.now().toString(36);ui.branchName='导入的支线 · '+next.year;ui.lastDecisionId=null;$('#main-dialog').close();store();renderAll();toast('存档已接回，原支线也已保留。');}catch(error){toast(error instanceof SyntaxError?'文件不是有效JSON，当前支线未改变。':error.message||'文件无法读取，原支线没有改变。');}finally{$('#import-file').value='';}}
function modal(title,html,kicker='THIS LIFE / 此生'){pause();$('#dialog-title').textContent=title;$('#dialog-kicker').textContent=kicker;$('#dialog-content').innerHTML=html;if(!$('#main-dialog').open)$('#main-dialog').showModal();}
function sourceMarkup(ids){const unique=[...new Set(A(ids))];return unique.map(id=>{const source=A(B.sources).find(s=>s.id===id);if(!source)return`<div class="source-item"><h4>${E(id)}</h4><p>本地资料索引中尚未找到这一来源。</p></div>`;const url=typeof source.url==='string'&&/^https?:\/\//i.test(source.url)?source.url:null;return`<div class="source-item"><h4>${E(source.id)} · ${E(source.title)}</h4>${source.note?`<p>${E(source.note)}</p>`:''}${url?`<a href="${E(url)}" target="_blank" rel="noopener noreferrer">打开本人记录 ↗</a>`:''}</div>`;}).join('')||'<p class="dialog-footnote">这部分没有列出本人来源；不据此补造经历。</p>';}
function recordSources(r){return[...new Set([...A(r?.sourceIds),...A(r?.events).flatMap(e=>A(e.sourceIds)),...A(bio(r?.year)?.sourceIds)])];}
function weightPool(draw){return A(draw?.pool||draw?.weights||draw?.candidates||draw?.entries);}
function detailNumber(n){return number(n)===null?'—':Number(n).toFixed(3).replace(/\.?0+$/,'');}
function humanize(value){const names={career:'事业',learning:'学习',resources:'资源',relationship:'关系',wellbeing:'身心',mobility:'流动',overall:'综合',energy:'精力',joy:'心情',craft:'做事手感',freedom:'自己安排',connection:'相处',reserve:'备用预算',opportunity:'机会',pressure:'阻力',balance:'净势',active:'进行中',paused:'暂放',testing:'试用',exploring:'探索',completed:'已完成'};return String(value??'').replace(/\b(career|learning|resources|relationship|wellbeing|mobility|overall|energy|joy|craft|freedom|connection|reserve|opportunity|pressure|balance|active|paused|testing|exploring|completed)\b/g,key=>names[key]);}
function weightTable(pool,selected){return pool.length?`<div class="weight-table-wrap"><table class="weight-table"><thead><tr><th>候选事件 / 入池条件</th><th>基础</th><th>命盘</th><th>状态</th><th>重心</th><th>重复</th><th>类型</th><th>权重</th><th>抽取份额</th></tr></thead><tbody>${pool.map(w=>`<tr class="${w.id===selected?'selected':''} ${w.eligible===false?'excluded':''}"><td>${E(w.label||w.title||'一个候选片段')}${w.eligible===false?`<small class="pool-exclusion">未入池：${E(A(w.exclusionReasons).length?A(w.exclusionReasons).map(humanize).join('；'):'不满足当次条件')}</small>`:''}</td><td>${detailNumber(w.baseWeight)}</td><td>${detailNumber(w.astroFactor)}</td><td>${detailNumber(w.stateFactor)}</td><td>${detailNumber(w.focusFactor)}</td><td>${detailNumber(w.noveltyFactor)}</td><td>${detailNumber(w.balanceFactor)}</td><td>${detailNumber(w.weight)}</td><td>${pct(w.probability)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="dialog-footnote">本条记录没有附完整候选池，不使用当前状态冒算过去的权重。</p>';}
function openYearAudit(eventIndex=null){
 if(!ui.run)return;
 const r=displayRecord(ui.selected),y=chart(ui.selected),future=r?.kind==='simulation',ev=Number.isInteger(eventIndex)?A(r?.events)[eventIndex]:null,audits=A(r?.selectionAudit);
 let html=`<p>${future?'这是这条支线在当年状态下生成的未来情境，不是已发生事实。':'这一页按公历归年；命盘按农历流年。个人记录不由随机抽签改写。'}</p><div class="audit-block"><h4>${ui.selected}年的命盘对照</h4><p>${y?`${E(y.startDate)} 至 ${E(y.endBefore)} 前一日，${E(y.stem)}${E(y.branch)}流年。流年命宫叠本命${E(y.annualPalace)}，${E(y.scopeName||'大限')}命宫叠本命${E(y.decadalPalace)}。`:'完整排盘请见资料馆。'}</p></div>`;
 if(ev)html+=`<div class="audit-block"><h4>${E(ev.title||'本次事件')}</h4><p>${E(humanize(ev.explanation||''))}</p>${number(ev.probability)!==null?`<p>本次内部抽取份额 ${pct(ev.probability)}，不是你个人在现实中的发生率。</p>`:''}${effectMarkup(ev.effectsApplied||ev.effects)?`<p>实际写入游戏状态：${E(effectMarkup(ev.effectsApplied||ev.effects))}。</p>`:''}</div>`;
 if(future){
  html+=`<div class="audit-block"><h4>当年抽签与条件权重</h4><p>先检查年龄、状态、路径与冷却条件；未入池的事件权重为0。入池后：基础 × 命盘 × 状态 × 重心 × 重复抑制 × 叙事类型平衡，再归一化为内部抽取份额。种子：${E(ui.run.seed)}。</p>${audits.map((draw,i)=>{
   const pool=weightPool(draw),chosen=pool.find(w=>w.id===draw.selectedId),event=A(r.events).find(e=>e.id===draw.selectedId),title=event?.title||draw.selectedLabel||chosen?.label||'本次选中的片段',basis=A(draw.basis).length?A(draw.basis):A(chosen?.basis),open=ev?ev.id===draw.selectedId:i===0;
   return`<details class="audit-draw" ${open?'open':''}><summary>第 ${i+1} 次抽选 · ${E(title)}</summary><div class="draw-selected"><strong>${E(title)}</strong><p>内部抽取份额 ${pct(chosen?.probability??event?.probability)} · 条件权重 ${detailNumber(chosen?.weight)}</p></div><ul class="draw-basis">${basis.slice(0,3).map(line=>`<li>${E(humanize(typeof line==='string'?line:line.text||''))}</li>`).join('')}</ul>${basis.length>3?`<details class="audit-basis-rest"><summary>展开其余 ${basis.length-3} 条命盘与状态依据</summary><ul>${basis.slice(3).map(line=>`<li>${E(humanize(typeof line==='string'?line:line.text||''))}</li>`).join('')}</ul></details>`:''}<p class="draw-roll">抽签值 ${number(draw.roll)===null?'未附':Number(draw.roll).toFixed(6)}${draw.poolHash?` · 候选池校验 ${E(draw.poolHash)}`:''}</p><details class="audit-full-pool"><summary>完整候选池 ${pool.length} 项：包含未入池条件 ↗</summary><p>表内因子保留三位小数。未入池先归零，不能用其余正因子的乘积推算份额。每次事件写入世界后，下一次重新计算。</p>${weightTable(pool,draw.selectedId)}</details></details>`;
  }).join('')||'<p class="dialog-footnote">这一条记录未附逐次候选池，不以当前条件冒充过去抽签。</p>'}</div><details class="audit-past-sources"><summary>这些事件的过去母题来处 ↗</summary><p>以下本人记录只提供过去偏好与创作线索，不是本年未来史料。</p>${sourceMarkup(ev?.sourceIds?.length?ev.sourceIds:recordSources(r))}</details>`;
 }else html+=`<div class="audit-block"><h4>本人记录来处</h4>${sourceMarkup(ev?.sourceIds?.length?ev.sourceIds:recordSources(r))}</div>`;
 if(!r||ui.selected>ui.run.year){try{const pool=api.previewWeights(ui.run,ui.run.year+1);html+=`<div class="audit-block"><h4>下一年 ${ui.run.year+1} 的候选池预览</h4><p>只预览当前状态的游戏选择权重，不表示事件已经发生。</p><details class="audit-full-pool"><summary>展开当前候选池 ↗</summary>${weightTable(A(pool))}</details></div>`;}catch(_){}}
 modal('这一年，为什么这样展开',html,'CONTEXT & CHANCE / 分层自查');
}
function openChartDetail(){const y=chart(ui.selected);if(!y)return;const layers=[['生年四化',y.natalMutations],[(y.scopeName||'大限')+'四化',y.decadalMutations],[`${y.year}${y.stem}${y.branch}流年四化`,y.annualMutations]];modal(`${ui.selected} · 三层主星与四化`,`${axisFor(ui.selected)?`<div class="axis-audit-heading"><span>这一年的主轴</span><h3>${E(axisFor(ui.selected).question||axisFor(ui.selected).title)}</h3>${axisProofMarkup(axisFor(ui.selected))}</div>`:''}<p>亮度与生年化曜取原局。限年四化是叠加引动，不混成生年性质。传记按公历归档，不把同页全部事件都绑定于这个流年。</p>${layers.map(([title,ms])=>`<div class="audit-block"><h4>${E(title)}</h4>${A(ms).map(m=>`<p>${E(m.star)} ${badge(m.type,title.includes('生年')?'生年':title.includes('流年')?'流年':y.scopeName||'大限')} · 落本命${E(m.natalPalace)}${m.annualPalace?'，叠流年'+E(m.annualPalace):''}${m.decadalPalace?'，叠本限'+E(m.decadalPalace):''}。</p>`).join('')}</div>`).join('')}<div class="dialog-buttons"><a class="dialog-action" href="archive.html?year=${ui.selected}">去十二宫与完整曲线 ↗</a></div>`);}
function openMethod(){modal('这条人生，怎样生成',`<div class="dialog-body"><p>起点固定：唐一航，公历2000年3月2日，男，绵阳；真太阳时14:59、未时。不会随机重生到另一种身份。</p><h3>来处保持原样，未来才会分歧</h3><p>截至2026-11-06的本人记录，按公历年份作为历史与当下的来处；缺失的年份保留缺口。2027起是条件式情境模拟。过去文档只提供人物偏好与创作母题，不是未来史料。</p><h3>重心、状态、选择与种子</h3><p>六项状态是游戏设定，初始值不是对本人健康、财富、幸福或能力的真实测量。年度重心与关键选择会改变模拟状态，再影响后续候选事件的权重与叙事。相同种子和选择可复现同一条支线。</p><p>事件权重用于内部抽选，不是经过统计验证的个人发生概率。每次抽取可在“这一年为什么这样展开”查看条件池、因子、抽签值和种子。不使用现实金额或生存曲线。</p><h3>命盘是一层独立对照</h3><p>原始排盘、主星亮度、生年/大限/流年四化与编辑曲线保持原值。命盘流年以农历年界为准，传记以公历归年；二者不能只因放在同一页就建立因果。紫微斗数没有经科学验证的个人未来预测效力。</p><h3>插画与书页边界</h3><p>插画为艺术化情境，部分有记录年份依据本人资料另作重构；均非现场照片。2000—2100是展示范围，不推断寿命、疾病或确定婚育与财富结果。</p><h3>存档留在这个浏览器</h3><p>模拟由本地纯函数引擎计算，无需把个人记录发往远程。使用引擎紧凑存档，最多保留四条本地支线；可导出、导入、比较或删除。打开窗口和回看历史会暂停，关闭后由你继续。</p><p><a href="storybook.html">传记底稿 ↗</a> · <a href="archive.html">完整命盘与底账 ↗</a> · <a href="https://1in8b.life/zh-hans/" target="_blank" rel="noopener noreferrer">时间与事件流的交互参考 ↗</a></p></div>`);}
function snapshotCurrent(){return{id:ui.branchId,name:ui.branchName,data:api.exportRun(ui.run),year:ui.run.year,seed:ui.run.seed};}
function canAddBranch(){if(ui.branches.length<3)return true;toast('本机已保留四条支线。请先导出或删除一条，再开始新的可能。');openStorage();return false;}
function switchBranch(id){const saved=ui.branches.find(b=>b.id===id);if(!saved)return;pause();try{const next=api.importRun(saved.data),current=snapshotCurrent();ui.branches=ui.branches.filter(b=>b.id!==id);ui.branches.push(current);ui.run=next;ui.branchId=saved.id;ui.branchName=saved.name;ui.selected=next.year;ui.lastDecisionId=null;$('#main-dialog').close();store();renderAll();toast('已回到“'+ui.branchName+'”。时间等你继续。');}catch(error){toast(error.message||'这一份支线暂时无法读取。');}}
function freshSeed(){return'tang-'+Date.now().toString(36);}
function openFork(){if(!ui.run)return;if(ui.run.pending){showDecision();return;}if(ui.selected>ui.run.year){toast('先走到这一年，再从这里另开一条支线。');return;}if(!canAddBranch())return;modal(`从 ${ui.selected} 年，换一种以后`,`<p>这一年及以前的经历和选择会保留。新的种子只改变往后的模拟流，不更改出生、个人记录或命盘。</p><label class="dialog-field">新支线名字<input id="fork-name" maxlength="36" value="${E(ui.selected+'年后的另一种可能')}"></label><label class="dialog-field">新的种子<input id="fork-seed" maxlength="120" value="${freshSeed()}" spellcheck="false"></label><p class="dialog-footnote">本机最多保留四条支线；原支线会留在存档里，可随时比较与切回。</p><div class="dialog-buttons"><button id="confirm-fork" class="primary">保留来处，开始新支线 →</button></div>`,'A DIFFERENT AFTER / 分岔');$('#confirm-fork').addEventListener('click',()=>{const seed=$('#fork-seed').value.trim(),name=$('#fork-name').value.trim();if(!seed){toast('给这条支线写一个种子。');return;}try{const next=api.fork(ui.run,ui.selected,{seed}),current=snapshotCurrent();ui.branches.push(current);ui.run=next;ui.branchId='branch-'+Date.now().toString(36);ui.branchName=name||ui.selected+'年后的另一种可能';ui.selected=next.year;ui.lastDecisionId=null;$('#main-dialog').close();store();renderAll();toast('旧支线已留存。新的以后，等你继续。');}catch(error){toast(error.message||'暂时无法从这一年分岔。');}});}
function startNew(startYear){if(!canAddBranch())return;const current=snapshotCurrent();try{const next=api.createRun({seed:freshSeed(),startYear,focus:'craft'});ui.branches.push(current);ui.run=next;ui.selected=next.year;ui.branchId='branch-'+Date.now().toString(36);ui.branchName=startYear===min?'从出生，重读来处':'从2026，再走一次';ui.lastDecisionId=null;$('#main-dialog').close();pause();store();renderAll();toast(startYear===min?'从出生观看；真实记录与缺口不会被随机改写。':'回到2026年，来处保持原样。');}catch(error){toast(error.message||'暂时不能重新开始。');}}
function exportCurrent(){if(!ui.run)return;try{const blob=new Blob([api.exportRun(ui.run)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='cisheng-'+ui.run.year+'-'+ui.branchId+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1200);toast('当前支线已导出，原进度仍在。');}catch(error){toast(error.message||'导出未完成，当前支线仍在。');}}
function branchSummary(run){return`<div class="branch-stats">${STAT.map(s=>`<span>${s.label}<b>${format(run.stats?.[s.id])}</b></span>`).join('')}</div>`;}
function openStorage(){if(!ui.run)return;const current=snapshotCurrent();modal('存档与支线',`<p>只保存在这个浏览器。当前共有 ${ui.branches.length+1} 条支线，最多四条；完整导出可带走进度，整理本地空间前请先保留文件。</p><div class="dialog-buttons"><button id="export-run" class="primary">导出当前支线 ↓</button><button id="import-run">导入一份存档 ↑</button><button id="storage-fork">从这一页分岔 ↗</button></div><article class="branch-row"><div><h3>${E(ui.branchName)} <small>当前</small></h3><p>${ui.run.year}年 · ${ui.run.year-min}岁 · ${E(ui.run.location||'')}<br>种子 ${E(ui.run.seed)}</p>${branchSummary(ui.run)}</div></article>${ui.branches.map(b=>{let r;try{r=api.importRun(b.data);}catch(_){return`<article class="branch-row"><div><h3>${E(b.name)}</h3><p>此份存档暂时无法读取。</p></div><div class="dialog-buttons"><button data-delete-branch="${E(b.id)}">删除这份</button></div></article>`;}return`<article class="branch-row"><div><h3>${E(b.name)}</h3><p>${r.year}年 · ${r.year-min}岁 · ${E(r.location||'')}<br>种子 ${E(r.seed)}</p>${branchSummary(r)}</div><div class="dialog-buttons"><button data-switch-branch="${E(b.id)}">回到这条</button><button data-compare-branch="${E(b.id)}">与当前比较</button><button data-delete-branch="${E(b.id)}">删除</button></div></article>`;}).join('')}${ui.recoveryBackups.length?`<h3>旧版本原档</h3><p>这些是版本变更前单独保留的原始存档，不会自动改写为新版本。</p><div class="dialog-buttons">${ui.recoveryBackups.map((b,i)=>`<button data-download-backup="${i}">下载旧版本备份 ${i+1}</button>`).join('')}</div>`:''}<p class="storage-previous"><a href="previous-edition.html">回看上一版支线 ↗</a></p><h3>换一个观看起点</h3><p>新开支线，原支线会保留。2026以前按记录顺序展开，不重掷历史。</p><div class="dialog-buttons"><button id="restart-present">从2026继续</button><button id="restart-birth">从出生观看</button></div>`,'LOCAL SAVES / 在此留存');$$('[data-download-backup]').forEach(button=>button.addEventListener('click',()=>{const ref=ui.recoveryBackups[Number(button.dataset.downloadBackup)];if(ref)downloadRawBackup(localStorage.getItem(ref.key),'cisheng-previous-version-'+(Number(button.dataset.downloadBackup)+1)+'.json');}));$('#export-run').addEventListener('click',exportCurrent);$('#import-run').addEventListener('click',()=>$('#import-file').click());$('#storage-fork').addEventListener('click',openFork);$('#restart-present').addEventListener('click',()=>startNew(cutoff));$('#restart-birth').addEventListener('click',()=>startNew(min));$$('[data-switch-branch]').forEach(b=>b.addEventListener('click',()=>switchBranch(b.dataset.switchBranch)));$$('[data-compare-branch]').forEach(b=>b.addEventListener('click',()=>openCompare(b.dataset.compareBranch)));$$('[data-delete-branch]').forEach(b=>b.addEventListener('click',()=>{ui.branches=ui.branches.filter(r=>r.id!==b.dataset.deleteBranch);store();openStorage();}));}
function openCompare(id){if(!ui.run)return;const branch=ui.branches.find(b=>b.id===id)||ui.branches.at(-1);if(!branch){modal('还没有另一条支线',`<p>从一个已经走过的年份分岔，保留来处，换一个种子。新的生活走势就可以和这一条放在一起看。</p><div class="dialog-buttons"><button id="compare-fork" class="primary">从 ${ui.selected} 年分岔 →</button></div>`);$('#compare-fork').addEventListener('click',openFork);return;}let other;try{other=api.importRun(branch.data);}catch(error){toast(error.message||'另一份支线无法读取。');return;}modal('同一个人，不同的以后',`<div class="compare-topline"><span><span style="color:#497b60">●</span> ${E(ui.branchName)}<br><span style="color:#b9563a">●</span> ${E(branch.name)}</span><select id="compare-metric" aria-label="比较哪一种模拟状态">${STAT.map(s=>`<option value="${s.id}" ${s.id===ui.metric?'selected':''}>${s.label}</option>`).join('')}</select></div><div id="compare-chart" class="compare-chart"></div><table class="compare-table"><thead><tr><th>此刻</th><th>${E(ui.branchName)}</th><th>${E(branch.name)}</th></tr></thead><tbody><tr><td>年份</td><td>${ui.run.year}</td><td>${other.year}</td></tr><tr><td>地点</td><td>${E(ui.run.location)}</td><td>${E(other.location)}</td></tr><tr><td>在做</td><td>${E(ui.run.vocation)}</td><td>${E(other.vocation)}</td></tr>${STAT.map(s=>`<tr><td>${s.label}</td><td>${format(ui.run.stats?.[s.id])}</td><td>${format(other.stats?.[s.id])}</td></tr>`).join('')}</tbody></table><p>这是两条模拟支线的状态比较，不是对现实的预测或测量。起点与原始命盘相同，往后的重心、条件、抽签与选择可以不同。</p><div class="dialog-buttons"><button id="compare-switch">回到“${E(branch.name)}” →</button><button id="compare-storage">查看全部支线</button></div>`,'BRANCHES / 两种以后');const draw=()=>{const metric=$('#compare-metric').value;$('#compare-chart').innerHTML=curveSvg([{name:ui.branchName,color:'#497b60',points:runPoints(ui.run,metric)},{name:branch.name,color:'#b9563a',points:runPoints(other,metric)}],{minYear:Math.min(...A(ui.run.timeline).map(r=>r.year),...A(other.timeline).map(r=>r.year),ui.run.year,other.year),maxYear:Math.max(ui.run.year,other.year),height:220});};draw();$('#compare-metric').addEventListener('change',draw);$('#compare-switch').addEventListener('click',()=>switchBranch(branch.id));$('#compare-storage').addEventListener('click',openStorage);}
function openDrawer(id){if(!ui.run)return;pause();closeDrawer();ui.drawer=id;const pane=$('#'+id);pane.classList.add('drawer-open');pane.setAttribute('role','dialog');pane.setAttribute('aria-modal','true');pane.setAttribute('aria-label',id==='identity-column'?'模拟状态与年度重心':'年格、命盘与生活');$('#drawer-shade').hidden=false;$('#close-drawer').hidden=false;document.body.classList.add('drawer-is-open');document.body.style.overflow='hidden';$('#close-drawer').focus();}
function closeDrawer(){if(ui.drawer){const pane=$('#'+ui.drawer);pane.classList.remove('drawer-open');pane.removeAttribute('role');pane.removeAttribute('aria-modal');pane.removeAttribute('aria-label');}ui.drawer=null;$('#drawer-shade').hidden=true;$('#close-drawer').hidden=true;document.body.classList.remove('drawer-is-open');document.body.style.overflow='';}
function downloadRawBackup(text=originalWorkspaceRaw,name='cisheng-original-backup.json'){if(typeof text!=='string'||!text){toast('没有可下载的原存档。');return;}const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1200);recoveryDownloaded=true;toast('原存档已交给浏览器下载。请保留这份文件，再开始新的一轮。');}
function recoverNewRun(){if(!api||!originalWorkspaceRaw)return;pause();let key=null;try{key=STORE+'-backup-'+Date.now().toString(36);localStorage.setItem(key,originalWorkspaceRaw);}catch(_){key=null;if(!recoveryDownloaded){toast('本机无法再存一份备份。请先下载原存档，再另开一轮。');return;}}try{const next=api.createRun({seed:freshSeed(),startYear:cutoff,focus:'craft'});ui.recoveryBackups=A(loadedWorkspace?.recoveryBackups).filter(b=>typeof b.key==='string'&&b.key.startsWith(STORE+'-backup-'));if(key)ui.recoveryBackups.push({key,date:new Date().toISOString()});ui.run=next;ui.branches=[];ui.branchId='recovered-'+Date.now().toString(36);ui.branchName='新的模拟 · 原档已保留';ui.selected=next.year;ui.lastDecisionId=null;loadedWorkspace=null;clearInterval(loaderTimer);$('#state-chart-metric').innerHTML=STAT.map(s=>`<option value="${s.id}">${s.label}</option>`).join('');renderAll();ui.ready=true;store();toast(key?'旧版本原档已单独备份。新的一轮从2026继续。':'旧版本原档已导出。新的一轮从2026继续。');}catch(error){loaderError(error.message||'新的一轮尚未开始，原档没有删除。');}}
function loaderError(message){$('#engine-status').hidden=false;$('#engine-status h2').textContent='故事还没接好，先停在这里。';$('#engine-status p').textContent=message||'引擎尚未就绪，全部个人记录和命盘仍在原入口。';$('#retry-engine').hidden=false;$('#engine-recovery').hidden=!originalWorkspaceRaw;$('#start-recovered').disabled=window.TANG_SIM?.rules?.version!==2;}
function boot(){if(ui.ready)return;if(!window.TANG_SIM||!window.SIM_EVENT_CATALOG)return;api=window.TANG_SIM;if(api.rules?.version!==2){loaderError('新版引擎与年度主轴正在接入。上一版支线仍可在旧页回看。');return;}try{if(originalWorkspaceRaw&&(!loadedWorkspace||loadedWorkspace.version!==2||typeof loadedWorkspace.current!=='string'))throw new Error('本机原存档格式暂时无法读取，原档仍保留。可先备份，再另开一轮。');if(loadedWorkspace?.version===2&&typeof loadedWorkspace.current==='string'){ui.run=api.importRun(loadedWorkspace.current);ui.branches=A(loadedWorkspace.branches).filter(b=>b&&typeof b.id==='string'&&typeof b.data==='string').slice(-3);ui.branchId=String(loadedWorkspace.branchId||'main');ui.branchName=String(loadedWorkspace.branchName||'上次的支线');ui.favorites=new Set(A(loadedWorkspace.favorites).map(Number).filter(yearValid));const speed=Number(loadedWorkspace.settings?.speed);if([1,2,4,8].includes(speed))ui.speed=speed;ui.autoChoose=loadedWorkspace.settings?.autoChoose===true;ui.recoveryBackups=A(loadedWorkspace.recoveryBackups).filter(b=>typeof b.key==='string'&&b.key.startsWith(STORE+'-backup-'));if(STAT.some(s=>s.id===loadedWorkspace.settings?.metric))ui.metric=loadedWorkspace.settings.metric;}else{ui.run=api.createRun({seed:'tang-2026',startYear:cutoff,focus:'craft'});}ui.selected=ui.run.year;clearInterval(loaderTimer);$('#state-chart-metric').innerHTML=STAT.map(s=>`<option value="${s.id}" ${s.id===ui.metric?'selected':''}>${s.label}</option>`).join('');renderAll();ui.ready=true;store();if(ui.run.pending&&!ui.autoChoose)showDecision();}catch(error){loaderError(error.message||'原进度暂时无法读取。可保留本地文件后重试。');}}
$('#toggle-play').addEventListener('click',togglePlay);$('#next-year').addEventListener('click',manualStep);$('#mobile-next').addEventListener('click',manualStep);$('#reopen-decision').addEventListener('click',showDecision);$('#close-decision').addEventListener('click',()=>$('#decision-dialog').close());$('#decision-dialog').addEventListener('close',pause);$('#main-dialog').addEventListener('close',pause);$('#close-main-dialog').addEventListener('click',()=>$('#main-dialog').close());$('#auto-choose').addEventListener('click',()=>{pause();ui.autoChoose=!ui.autoChoose;store();renderControls();});$$('[data-speed]').forEach(b=>b.addEventListener('click',()=>{ui.speed=Number(b.dataset.speed);store();renderControls();if(!ui.paused)schedule();}));$('#return-live').addEventListener('click',()=>viewYear(ui.run.year));$('#favorite-current').addEventListener('click',()=>favorite(ui.selected));$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{pause();ui.filter=b.dataset.filter;ui.limit=12;renderStream();}));$('#load-older').addEventListener('click',()=>{pause();ui.limit+=12;renderStream();});$('#state-chart-metric').addEventListener('change',e=>{ui.metric=e.target.value;store();renderCurves();});$('#open-method').addEventListener('click',openMethod);$('#open-storage').addEventListener('click',openStorage);$('#open-branches').addEventListener('click',()=>openCompare());$('#fork-here').addEventListener('click',openFork);$('#fork-selected').addEventListener('click',openFork);$('#open-year-audit').addEventListener('click',()=>openYearAudit());$('#open-chart-detail').addEventListener('click',openChartDetail);$('#compact-stars').addEventListener('click',openChartDetail);$('#show-draw').addEventListener('click',()=>openYearAudit());$('#open-stats-help').addEventListener('click',()=>modal('模拟状态，不是现实测量',`<p>这六项是让故事发生取舍的游戏状态，范围0–100。历史与当下的初始值同样是游戏设定，不代表本人健康、财富、幸福或能力的检测结果。</p>${FOCUS.map(f=>`<div class="audit-block"><h4>${E(f.label)}</h4><p>${E(f.text)}</p></div>`).join('')}<p>较高的状态可能改变候选事件权重，但不会保证某个结果。支线曲线呈现这次模拟，命盘编辑曲线是另一层对照。</p>`));$('#import-file').addEventListener('change',e=>importFile(e.target.files?.[0]));$$('[data-command]').forEach(b=>b.addEventListener('click',()=>{$('#mobile-nav').hidden=true;$('#mobile-menu').setAttribute('aria-expanded','false');b.dataset.command==='method'?openMethod():openStorage();}));$('#mobile-menu').addEventListener('click',()=>{pause();const nav=$('#mobile-nav');nav.hidden=!nav.hidden;$('#mobile-menu').setAttribute('aria-expanded',String(!nav.hidden));});$$('[data-drawer]').forEach(b=>b.addEventListener('click',()=>openDrawer(b.dataset.drawer)));$('#close-drawer').addEventListener('click',closeDrawer);$('#drawer-shade').addEventListener('click',closeDrawer);document.addEventListener('keydown',e=>{if(ui.drawer&&e.key==='Escape'){closeDrawer();return;}if(ui.drawer&&e.key==='Tab'){const nodes=[$('#close-drawer'),...$$('#'+ui.drawer+' button:not(:disabled), #'+ui.drawer+' a, #'+ui.drawer+' select, #'+ui.drawer+' summary')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}return;}if($$('dialog[open]').length||ui.drawer||/INPUT|SELECT|TEXTAREA|BUTTON|A|SUMMARY/.test(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;if(e.code==='Space'){e.preventDefault();togglePlay();}else if(e.key==='ArrowRight'){e.preventDefault();manualStep();}});document.addEventListener('toggle',e=>{if(e.target.tagName==='DETAILS'&&e.target.open)pause();},true);document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});window.addEventListener('tang-sim:ready',boot);window.addEventListener('resize',()=>{if(innerWidth>720&&ui.drawer)closeDrawer();});$('#retry-engine').addEventListener('click',()=>location.reload());$('#download-old-save').addEventListener('click',()=>downloadRawBackup());$('#start-recovered').addEventListener('click',recoverNewRun);loaderTimer=setInterval(boot,300);setTimeout(()=>{if(!ui.ready)loaderError('引擎仍在载入；可以刷新重试，或先打开传记底稿。');},15000);boot();
window.CISHENG_SIM_UI={viewYear,pause,getRun:()=>ui.run,getState:()=>({year:ui.run?.year,selected:ui.selected,paused:ui.paused,speed:ui.speed,autoChoose:ui.autoChoose,branches:ui.branches.length+1})};
